def flatten(items, depth=None):
    """Flattens nested lists into one list.

    depth limits how many levels of nesting are removed. None flattens
    completely, 0 returns a shallow copy. Negative depth raises ValueError.
    Strings are never split.
    """
    if depth is not None and depth < 0:
        raise ValueError("depth must be non-negative or None")
    out = []
    for item in items:
        if isinstance(item, list) and (depth is None or depth > 0):
            out.extend(flatten(item, None if depth is None else depth - 1))
        else:
            out.append(item)
    return out

